//! SO-ARM101 embedded as a 6R chain (internal model).
//!
//! The five-joint arm plus one zero-offset virtual wrist joint, so that the ssik / dexforge
//! pipeline (which handles only full 6R and 7R chains) can generate its closed-form IK,
//! kinematics and dynamics. There is no hardware driver for this chain: use
//! [`so101`](crate::so101), which pins the virtual joint to zero.
//!
//! Scaffolded by `codegen/scaffold.py`. `arm.rs` and `generated_*.rs` are regenerated by the
//! codegen scripts; `ik_solver.rs` is a mechanical translation of the ssik artifact (see its module docs).

pub mod arm;
pub mod generated_dynamics;
pub mod generated_kinematics;
pub mod ik_solver;

pub use arm::{So1016r, DOF, MAX_SOLUTIONS};

